// План specs/gps-workflow.md 4.1–4.2 (кейсы .qa/tests/gps-workflow/GW-07, GW-08). PROD, gps (компания «בדיקה»), EN. Только просмотр.
// Разметка сверена с бандлом app.techory.ai 12.11 (GPSWorkflow): список сообщений — <aside> (complementary, max-h 45vh на телефоне)
// с <ul> overflow-y-auto; карта — соседний <section> (h-[70vh], на lg — слева, aside справа w-400); страница прокручивается в <main>;
// плавающая «+» — кнопка «Create new». Скриншоты QA: 772441-375x812-*, 772441-1440-desktop.png.
import { test, expect } from '../../fixtures';
import type { Locator, Page } from '@playwright/test';
import { ROLE, messageList, openGpsAll, prepare } from './gps-helpers';

type Box = { x: number; y: number; width: number; height: number };

const listPanel = (page: Page) => page.getByRole('complementary').filter({ has: page.getByRole('tab', { name: 'All' }) });
/** Карта — <section> рядом со списком (общий родитель flex). */
const mapSection = (page: Page) => listPanel(page).locator('xpath=preceding-sibling::section[1] | following-sibling::section[1]').first();

async function box(l: Locator, what: string): Promise<Box> {
  const b = await l.boundingBox();
  expect(b, `${what}: есть на странице`).not.toBeNull();
  return b as Box;
}

const intersects = (a: Box, b: Box) =>
  a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;

test.describe('GPS Workflow — вёрстка на телефоне (#772441)', () => {
  test('Mobile: message list above the map with its own scroll, map ~70% of screen height #772441 @mobile @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await prepare(page);
    await openGpsAll(page);
    const list = messageList(page);
    await expect(list.getByRole('button').first(), 'во вкладке All есть сообщения (предусловие)').toBeVisible({ timeout: 30_000 });
    const map = mapSection(page);
    await expect(map).toBeVisible();

    // Т1: список над картой (источник: «מה רצוי» — «רשימת האנשים (העבודות) תהיה מעל המפה»)
    const listBox = await box(listPanel(page), 'список');
    const mapBox = await box(map, 'карта');
    expect(listBox.y + listBox.height, 'низ списка ≤ верх карты').toBeLessThanOrEqual(mapBox.y + 1);

    // Т2: список компактный и прокручивается сам (источник: «הרשימה קומפקטית ונגללת»)
    const scroll = await list.evaluate((el) => ({
      overflowY: getComputedStyle(el).overflowY,
      scrollHeight: el.scrollHeight,
      clientHeight: el.clientHeight,
    }));
    expect(scroll.overflowY, 'overflow-y списка').toBe('auto');
    expect(scroll.scrollHeight, 'во вкладке All список длиннее своей высоты — есть своя прокрутка').toBeGreaterThan(scroll.clientHeight);

    // Т3: карта не полоса — ~70% высоты экрана (источник: «המפה בגובה מלא»; коммент программиста — ~70%)
    const vh = await page.evaluate(() => window.innerHeight);
    const ratio = mapBox.height / vh;
    expect(ratio, `высота карты ${Math.round(mapBox.height)} px / окно ${vh} px`).toBeGreaterThan(0.65);
    expect(ratio).toBeLessThan(0.75);
  });

  test('Mobile: after scrolling the page down the whole map is in view and the "+" button does not cover it #772441 @mobile @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await prepare(page);
    await openGpsAll(page);
    const map = mapSection(page);
    await expect(map).toBeVisible();
    const fab = page.getByRole('button', { name: 'Create new' }).filter({ visible: true }).first();
    await expect(fab, 'плавающая «+»').toBeVisible();

    // Прокрутка страницы (main) до конца
    const main = page.getByRole('main');
    await main.evaluate((el) => el.scrollTo(0, el.scrollHeight));
    await expect.poll(() => main.evaluate((el) => Math.ceil(el.scrollTop + el.clientHeight) >= el.scrollHeight - 1), { message: 'main прокручен до конца' }).toBe(true);

    // Т3/Т4: карта целиком в окне, «+» с ней не пересекается (источник: «המפה … לא מכוסה בכפתור "+"»; коммент — отступ внизу)
    await expect.poll(async () => {
      const m = await map.boundingBox();
      const vh = await page.evaluate(() => window.innerHeight);
      return !!m && m.y >= 0 && m.y + m.height <= vh + 1;
    }, { message: 'карта целиком в окне после прокрутки' }).toBe(true);
    const mapBox = await box(map, 'карта');
    const fabBox = await box(fab, '«+»');
    expect(intersects(mapBox, fabBox), `«+» ${JSON.stringify(fabBox)} не пересекает карту ${JSON.stringify(mapBox)}`).toBe(false);
  });

  test('Desktop 1440: map on the left, message list on the right in one row #772441 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await prepare(page);
    await openGpsAll(page);
    const map = mapSection(page);
    await expect(map).toBeVisible();
    const listBox = await box(listPanel(page), 'список');
    const mapBox = await box(map, 'карта');

    // П2: десктоп без изменений — карта слева, список справа (коммент программиста)
    expect(mapBox.x + mapBox.width, 'правый край карты ≤ левый край списка').toBeLessThanOrEqual(listBox.x + 1);
    expect(Math.abs(mapBox.y - listBox.y), 'карта и список начинаются на одной высоте (одна строка)').toBeLessThanOrEqual(2);
    expect(listBox.y, 'список не под картой').toBeLessThan(mapBox.y + mapBox.height);
  });
});
